local function StylePins(pool, scope)
    local prefix = scope == "map" and "mapshowNextSteps" or "minimapshowNextSteps"
    local profile = APR.settings.profile
    for _, pin in pairs(pool) do
        pin:SetSize(profile[prefix .. "Size"], profile[prefix .. "Size"])
        if pin.guidancePoint and Constants.guidanceIcons[pin.guidancePoint.kind or pin.guidancePoint.type] then
            pin.icon:SetVertexColor(1, 1, 1)
        else
            pin.icon:SetVertexColor(unpack(profile[prefix .. "Color"]))
        end
        APR:ApplyTextStyle(
            pin.text,
            scope,
            { colorProfileKey = prefix .. "ColorText", sizeScaleProfileKey = prefix .. "TextScale" }
        )
    end
end--[[APR_DIAG]]; StylePins = APRTrace("APR-Core/features/navigation/map/MapPins.lua:61:StylePins#4", StylePins)--[[/APR_DIAG]]

function APR.map:UpdateMapIconsStyle()
    StylePins(self.pinlist, "map")
    StylePins(self.guidancePinlist, "map")
end--[[APR_DIAG]]; APR.map.UpdateMapIconsStyle = APRTrace("APR-Core/features/navigation/map/MapPins.lua:79:APR.map:UpdateMapIconsStyle#5", APR.map.UpdateMapIconsStyle)--[[/APR_DIAG]]

function APR.map:UpdateMiniMapIconsStyle()
    StylePins(self.minimapPinlist, "minimap")
    StylePins(self.guidanceMinimapPinlist, "minimap")
end--[[APR_DIAG]]; APR.map.UpdateMiniMapIconsStyle = APRTrace("APR-Core/features/navigation/map/MapPins.lua:84:APR.map:UpdateMiniMapIconsStyle#6", APR.map.UpdateMiniMapIconsStyle)--[[/APR_DIAG]]

local function RemovePins(pool, world)
    if not pool or not next(pool) then return end
    for _, pin in pairs(pool) do
        pin:Hide()
        pin:ClearAllPoints()
    end
    if world then
        hbdPins:RemoveAllWorldMapIcons(pool)
    else
        hbdPins:RemoveAllMinimapIcons(pool)
    end
end--[[APR_DIAG]]; RemovePins = APRTrace("APR-Core/features/navigation/map/MapPins.lua:89:RemovePins#7", RemovePins)--[[/APR_DIAG]]

function APR.map:RemoveMapIcons()
    RemovePins(self.pinlist, true)
    RemovePins(self.guidancePinlist, true)
end--[[APR_DIAG]]; APR.map.RemoveMapIcons = APRTrace("APR-Core/features/navigation/map/MapPins.lua:102:APR.map:RemoveMapIcons#8", APR.map.RemoveMapIcons)--[[/APR_DIAG]]

function APR.map:RemoveMiniMapIcons()
    RemovePins(self.minimapPinlist, false)
    RemovePins(self.guidanceMinimapPinlist, false)
end--[[APR_DIAG]]; APR.map.RemoveMiniMapIcons = APRTrace("APR-Core/features/navigation/map/MapPins.lua:107:APR.map:RemoveMiniMapIcons#9", APR.map.RemoveMiniMapIcons)--[[/APR_DIAG]]

local function AcquirePin(self, pool, key, stepIndex, step, scope, guidance)
    local prefix = scope == "map" and "mapshowNextSteps" or "minimapshowNextSteps"
    local profile, pin = APR.settings.profile, pool[key]
    if not pin then
        pin = self:CreatePin(
            stepIndex,
            step,
            profile[prefix .. "Size"],
            profile[prefix .. "Color"],
            scope,
            prefix .. "ColorText",
            prefix .. "TextScale"
        )
        if guidance and guidance.kind == "map_waypoint" then
            pin:RegisterForClicks("RightButtonUp", "LeftButtonUp")
            pin:SetScript("OnClick", --[[APR_DIAG]]APRTrace("APR-Core/features/navigation/map/MapPins.lua:127:callback#11", --[[/APR_DIAG]]function(_, button)
                local services = APR.Services
                local active = services and services.active
                if
                    active
                    and active.step._mapWaypoint
                    and (
                        button == "RightButton"
                        or (button == "LeftButton" and IsControlKeyDown and IsControlKeyDown())
                    )
                then
                    services:Cancel()
                end
            end--[[APR_DIAG]])--[[/APR_DIAG]])
        end
        pool[key] = pin
    end
    pin.stepIndex, pin.step, pin.guidancePoint = stepIndex, step, guidance
    pin.text:SetText(guidance and "" or stepIndex)
    if guidance and pin.icon then
        local icon = Constants.guidanceIcons[guidance.kind or guidance.type]
        pin.icon:SetTexture(icon or "Interface\\Addons\\APR\\APR-Core\\assets\\Icon.tga")
        if icon then pin.icon:SetVertexColor(1, 1, 1) end
    end
    return pin
end--[[APR_DIAG]]; AcquirePin = APRTrace("APR-Core/features/navigation/map/MapPins.lua:112:AcquirePin#10", AcquirePin)--[[/APR_DIAG]]

local function PlaceWorldPin(pool, pin, mapID, x, y)
    if mapID == Constants.WORLD_MAP_ID or mapID == Constants.COSMIC_MAP_ID then return end
    hbdPins:AddWorldMapIconMap(pool, pin, mapID, x, y, 3)
end--[[APR_DIAG]]; PlaceWorldPin = APRTrace("APR-Core/features/navigation/map/MapPins.lua:154:PlaceWorldPin#12", PlaceWorldPin)--[[/APR_DIAG]]

-- Static search locations share one quest step; they are neither waypoints
-- to visit in order nor a live position for a roaming NPC.
local function PlaceSearchMarkers(self, step, stepIndex, routeMapID, mapID, playerMapID, showWorldPins)
    local profile = APR.settings.profile
    for index, coord in ipairs(step.MapMarkers or {}) do
        local point = {
            Coord = coord,
            uiMapID = coord.mapID or step.Zone or routeMapID,
            instanceID = coord.instanceID or step.instanceID,
        }
        if APR.navigationPreview then
            point.instanceID = point.instanceID or APR.navigationPreview:GetMapInstance(point.uiMapID)
        end
        local key = "search-" .. index
        if showWorldPins and (profile.mapshowNextStepsCount or 0) > 0 then
            local x, y = Project(point, mapID)
            if x and y and x >= 0 and x <= 1 and y >= 0 and y <= 1 then
                local pin = AcquirePin(self, self.pinlist, key, stepIndex, step, "map")
                PlaceWorldPin(self.pinlist, pin, mapID, x, y)
            end
        end
        if profile.minimapshowNextSteps and (profile.minimapshowNextStepsCount or 0) > 0 then
            local x, y = Project(point, playerMapID)
            if x and y then
                local pin = AcquirePin(self, self.minimapPinlist, key, stepIndex, step, "minimap")
                hbdPins:AddMinimapIconMap(self.minimapPinlist, pin, playerMapID, x, y, true, true)
            end
        end
    end
end--[[APR_DIAG]]; PlaceSearchMarkers = APRTrace("APR-Core/features/navigation/map/MapPins.lua:161:PlaceSearchMarkers#13", PlaceSearchMarkers)--[[/APR_DIAG]]

function APR.map:AddMapPins()
    self.pendingPinRefresh = nil
    self.pinMapID = WorldMapFrame:GetMapID()
    self.pinWidth, self.pinHeight = WorldMapButton:GetWidth(), WorldMapButton:GetHeight()
    if APR.navigationPreview then APR.navigationPreview.routeCache = nil end
    self:RemoveMapIcons()
    self:RemoveMiniMapIcons()
    local profile = APR.settings.profile
    if
        not (
            APR.ActiveRoute
            or (APR.Services and APR.Services.active)
            or (APR.navigation and APR.navigation.queue and #APR.navigation.queue > 0)
            or (APR.navigationPreview and #APR.navigationPreview:GetPoints() > 0)
        )
    then
        return
    end
    local service = APR.Services and APR.Services.active
    local waypoint = service and service.step and service.step._mapWaypoint
    if
        not profile.enableAddon or (not waypoint and not profile.mapshowNextSteps and not profile.minimapshowNextSteps)
    then
        return
    end
    local mapID, playerMapID = WorldMapFrame:GetMapID(), C_Map.GetBestMapForUnit("player")
    local canShowWorldPins = mapID ~= Constants.COSMIC_MAP_ID and mapID ~= Constants.WORLD_MAP_ID
    local showWorldPins = profile.mapshowNextSteps and canShowWorldPins
    if APR.navigationPreview then
        local guidanceSlot = 0
        for _, point in ipairs(APR.navigationPreview:GetPoints()) do
            if point.generated and not point.terrainBend then
                local manual = point.kind == "map_waypoint"
                local key = "map-waypoint"
                if not manual then
                    guidanceSlot = guidanceSlot + 1
                    key = "guidance-" .. guidanceSlot
                end
                if showWorldPins or (manual and canShowWorldPins) then
                    local x, y = Project(point, mapID)
                    if x and y and x >= 0 and x <= 1 and y >= 0 and y <= 1 then
                        local pin = AcquirePin(self, self.guidancePinlist, key, nil, nil, "map", point)
                        PlaceWorldPin(self.guidancePinlist, pin, mapID, x, y)
                    end
                end
                if profile.minimapshowNextSteps or manual then
                    local x, y = Project(point, playerMapID)
                    if x and y then
                        local pin = AcquirePin(self, self.guidanceMinimapPinlist, key, nil, nil, "minimap", point)
                        hbdPins:AddMinimapIconMap(self.guidanceMinimapPinlist, pin, playerMapID, x, y, true, true)
                    end
                end
            end
        end
    end
    local progress = APRData and APRData[APR.PlayerID]
    local current = progress and APR.ActiveRoute and progress[APR.ActiveRoute]
    if not current or not APR.RouteQuestStepList or not APR.RouteQuestStepList[APR.ActiveRoute] then return end
    local worldCount, miniCount = profile.mapshowNextStepsCount or 0, profile.minimapshowNextStepsCount or 0
    -- Generated guidance above has its own visibility policy. Only authored
    -- markers need route resolution and live filtered numbering below.
    if (not showWorldPins or worldCount <= 0) and (not profile.minimapshowNextSteps or miniCount <= 0) then return end
    local worldUsed, miniUsed, filtered = 0, 0, 0
    local route = APR:GetRouteSteps(APR.ActiveRoute)
    local definition = APR.RouteQuestStepList[APR.ActiveRoute]
    local routeMapID = definition.mapID or tonumber(APR.ActiveRoute:match("^(%d+)"))
    local last = math.min(#route, current + math.max(worldCount, miniCount))
    local zoneHint = APR:GetPlayerParentMapID()
    for index = 1, last do
        local step = route[index]
        local visible = APR:StepFilterQoL(step)
        if not visible then filtered = filtered + 1 end
        if visible and index == current then
            PlaceSearchMarkers(self, step, index - filtered, routeMapID, mapID, playerMapID, showWorldPins)
        end
        local coord, zone
        if visible and index >= current then
            coord, zone = APR:GetStepCoord(step, routeMapID, zoneHint)
        end
        if coord then
            local point = {
                Coord = coord,
                uiMapID = coord.mapID or zone or step.Zone or routeMapID,
                instanceID = coord.instanceID or step.instanceID,
            }
            if APR.navigationPreview then
                point.instanceID = point.instanceID or APR.navigationPreview:GetMapInstance(point.uiMapID)
            end
            local stepIndex = index - filtered
            if showWorldPins and worldUsed < worldCount then
                local x, y = Project(point, mapID)
                if x and y and x >= 0 and x <= 1 and y >= 0 and y <= 1 then
                    local pin = AcquirePin(self, self.pinlist, worldUsed + 1, stepIndex, step, "map")
                    PlaceWorldPin(self.pinlist, pin, mapID, x, y)
                    worldUsed = worldUsed + 1
                end
            end
            if profile.minimapshowNextSteps and miniUsed < miniCount then
                local x, y = Project(point, playerMapID)
                if x and y then
                    local pin = AcquirePin(self, self.minimapPinlist, miniUsed + 1, stepIndex, step, "minimap")
                    hbdPins:AddMinimapIconMap(self.minimapPinlist, pin, playerMapID, x, y, true, true)
                    miniUsed = miniUsed + 1
                end
            end
        end
    end
end--[[APR_DIAG]]; APR.map.AddMapPins = APRTrace("APR-Core/features/navigation/map/MapPins.lua:190:APR.map:AddMapPins#14", APR.map.AddMapPins)--[[/APR_DIAG]]
-- Batch pin notifications independently of the optional live line animation.
function APR.map:QueueMapPins()
    if not self.stepLines or not C_Timer or not C_Timer.NewTimer then
        self:AddMapPins()
        self:RefreshActivity()
        return
    end
    if self.pinRefreshTimer then return end
    self.pendingPinRefresh = true
    local timer
    timer = C_Timer.NewTimer(0, --[[APR_DIAG]]APRTrace("APR-Core/features/navigation/map/MapPins.lua:308:callback#16", --[[/APR_DIAG]]function()
        if self.pinRefreshTimer ~= timer then return end
        self.pinRefreshTimer = nil
        self.pendingPinRefresh = nil
        self:AddMapPins()
        self:RefreshActivity()
    end--[[APR_DIAG]])--[[/APR_DIAG]])
    self.pinRefreshTimer = timer
end--[[APR_DIAG]]; APR.map.QueueMapPins = APRTrace("APR-Core/features/navigation/map/MapPins.lua:299:APR.map:QueueMapPins#15", APR.map.QueueMapPins)--[[/APR_DIAG]]

function APR.map:ToggleMapPins()
    if self.pinRefreshTimer then
        self.pinRefreshTimer:Cancel()
        self.pinRefreshTimer = nil
    end
    self.pendingPinRefresh = nil
    self:AddMapPins()
    self:RefreshActivity()
end--[[APR_DIAG]]; APR.map.ToggleMapPins = APRTrace("APR-Core/features/navigation/map/MapPins.lua:318:APR.map:ToggleMapPins#17", APR.map.ToggleMapPins)--[[/APR_DIAG]]
